"""Actual HTTP with emulated phones; desktop/TV inputs stubbed, no physical-device claim."""
from test_personalities_remote import PersonalitiesRemote
class OperationsRemote(PersonalitiesRemote):
 def test_ops_paired_controls_match_host_and_no_remote_world(self):
  pc=self.page(pc=True);pc.wait_for_function('document.querySelector("#rd-bridge-status").textContent.includes("LINKED")');phone=self.page(width=390,height=844);self.tab(phone,'icarus');phone.wait_for_selector('.engineering-systems');phone.locator('.systems-zone').select_option('cargo');phone.locator('.systems-target').select_option('0');phone.locator('[data-op="gravity"]').click();pc.wait_for_function('__icarusSoak.snapshot().shipSystems.zones.cargo.targetG===0');pc.evaluate('__icarusSoak.advance(6)');phone.wait_for_function('document.querySelector(".systems-readout").textContent.includes("0.00g actual")');self.assertEqual(phone.evaluate('typeof __icarusSoak'),'undefined');self.assertEqual(phone.evaluate('typeof ICARUSShipSystems'),'undefined');self.assertEqual(pc.evaluate('__icarusSoak.snapshot().shipSystems.zones.medical.g'),1);self.assertNotIn('shipSystems',self.m.ICARUS_BRIDGE['telemetry']);self.assertLessEqual(phone.evaluate('document.documentElement.scrollWidth'),392)
 def test_ops_validation_dedup_and_independent_local_outage(self):
  pc=self.page(pc=True);pc.wait_for_function('document.querySelector("#rd-bridge-status").textContent.includes("LINKED")');auth={'Authorization':'Bearer test-client'}
  for c in ['systems:gravity:cargo:9','systems:gravity:no-room:0','systems:restore:science:explode','systems:maintain:FAKE']:
   self.assertEqual(self.req('/api/icarus/dispatch',{'command':c,'requestId':'invalid-system-'+str(len(c))},auth)[0],400)
  self.assertEqual(self.req('/api/icarus/dispatch',{'command':'systems:gravity:cargo:0','requestId':'unpaired-system'})[0],401)
  command={'command':'systems:circuit:cargo:0','requestId':'once-only-local-circuit'};a=self.req('/api/icarus/dispatch',command,auth);b=self.req('/api/icarus/dispatch',command,auth);self.assertEqual(a[1]['queued'],b[1]['queued']);pc.wait_for_function('__icarusSoak.snapshot().shipSystems.zones.cargo.circuitIsolated');pc.evaluate('__icarusSoak.advance(1)');rooms=pc.evaluate('__icarusSoak.observation().rooms');self.assertFalse(next(r for r in rooms if r['id']=='C03')['available']);self.assertTrue(next(r for r in rooms if r['id']=='A01')['available']);self.assertEqual(pc.evaluate('__icarusSoak.snapshot().resourceAudit'),[])
